public static void makekrakentreasures(DzBuilder world, int cposx, int cposy, int cposz, int width) {
      for (int i = 5; i < width - 5; i += 6) {
         makekrakentreasure(world, cposx + i, cposy, cposz + 5, 1);
      }

      for (int var8 = 5; var8 < width - 5; var8 += 6) {
         makekrakentreasure(world, cposx + var8, cposy, cposz + 10, 1);
      }

      for (int var9 = 5; var9 < width - 5; var9 += 6) {
         makekrakentreasure(world, cposx + var9, cposy, cposz + 15, 1);
      }

      for (int var10 = 5; var10 < width - 5; var10 += 6) {
         makekrakentreasure(world, cposx + var10, cposy, cposz + 25, 3);
      }

      for (int var11 = 5; var11 < width - 5; var11 += 6) {
         makekrakentreasure(world, cposx + var11, cposy, cposz + 30, 3);
      }

      for (int var12 = 5; var12 < width - 5; var12 += 6) {
         makekrakentreasure(world, cposx + var12, cposy, cposz + 35, 3);
      }
   }

public static void makekrakentreasure(DzBuilder world, int cposx, int cposy, int cposz, int dir) {
      if (dir == 1) {
         world.set(cposx - 1, cposy, cposz, block("grassblock"));
         world.set(cposx - 1, cposy + 1, cposz, block("blockflower_scary"));
         world.set(cposx - 1, cposy, cposz + 1, block("grassblock"));
         world.set(cposx - 1, cposy + 1, cposz + 1, block("blockflower_black"));
         world.set(cposx + 1, cposy, cposz, block("grassblock"));
         world.set(cposx + 1, cposy + 1, cposz, block("blockflower_scary"));
         world.set(cposx + 1, cposy, cposz + 1, block("grassblock"));
         world.set(cposx + 1, cposy + 1, cposz + 1, block("blockflower_black"));
         world.set(cposx, cposy + 1, cposz, block("glass"));
         world.set(cposx, cposy + 1, cposz + 1, block("glass"));
         world.chest(cposx, cposy + 1, cposz - 1, "GemStuff");
         world.chest(cposx, cposy + 1, cposz + 2, "FoodStuff");
      }

      if (dir == 3) {
         world.set(cposx - 1, cposy, cposz, block("grassblock"));
         world.set(cposx - 1, cposy + 1, cposz, block("blockflower_scary"));
         world.set(cposx - 1, cposy, cposz - 1, block("grassblock"));
         world.set(cposx - 1, cposy + 1, cposz - 1, block("blockflower_black"));
         world.set(cposx + 1, cposy, cposz, block("grassblock"));
         world.set(cposx + 1, cposy + 1, cposz, block("blockflower_scary"));
         world.set(cposx + 1, cposy, cposz - 1, block("grassblock"));
         world.set(cposx + 1, cposy + 1, cposz - 1, block("blockflower_black"));
         world.set(cposx, cposy + 1, cposz, block("glass"));
         world.set(cposx, cposy + 1, cposz - 1, block("glass"));
         world.chest(cposx, cposy + 1, cposz + 1, "GemStuff");
         world.chest(cposx, cposy + 1, cposz - 2, "FoodStuff");
      }
   }
